\begin{theorem}[Full sequential convergence]
\label{t:full}
Suppose that Assumption~\ref{a:standing} holds, that $\sum_{i=1}^m f_i(x_i)+P(\mathbf{x})-G(\mathbf{x})$ is coercive, that $H$ is bounded below, that $G$ is differentiable with $\ell_G$-Lipschitz continuous gradient, and that, for all $i\in \{1, \dots, m\}$, $\nabla{\phi_i}$ is $\ell_{\phi}$-Lipschitz continuous. Let $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ be the sequence generated by Algorithm~\ref{algo:BPLA} with $z_0\in \Ima(B)$ and $\limsup_{n\to +\infty} \mu_n =\overline{\mu} <+\infty$.
Define
\begin{align*}
\mathcal{F}(\mathbf{x},y,z,t):=\mathcal{L}_\rho(\mathbf{x},y,z) +c\|y-t\|^2, \text{~~where~} c=\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}.
\end{align*}
\begin{enumerate}
\item\label{t:full_cvg} 
Suppose that $\mathcal{F}$ is a KL function. Then the sequence $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ converges to a stationary point $(\mathbf{x}^{*},y^{*},z^{*})$ of $\mathcal{L}_\rho$ and \begin{align*}
\sum_{n=0}^{+\infty} \|(\mathbf{x}_{n+1},y_{n+1},z_{n+1})-(\mathbf{x}_{n},y_{n},z_{n})\| < +\infty.
\end{align*}
\item\label{t:full_rate} 
Suppose that $\mathcal{F}$ is a KL function with exponent $\kappa\in [0,1)$. Then the following hold:
\begin{enumerate}
\item\label{t:full_rate_finite}
If $\kappa =0$, then $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ converges to $(\mathbf{x}^{*},y^{*},z^{*})$ in a finite number of steps. 
\item\label{t:full_rate_linear}
If $\kappa\in (0,\frac{1}{2}]$, then there exist $\overline{\gamma}\in \mathbb{R}_{++}$ and $\zeta\in \left(0,1\right)$ such that, for all $n\in \mathbb{N}$, 
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \overline{\gamma}\zeta^{\frac{n}{2}}, \\
&\|\mathbf{Ax}_n+By_n-b\| \leq \overline{\gamma} \zeta^{\frac{n}{2}}, \\
&\lvert \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) -\mathcal{L}_\rho(\mathbf{x}^{*},y^{*},z^{*}) \rvert \leq \overline{\gamma}\zeta^n, \\
\text{and~} &|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| \leq \overline{\gamma} \zeta^{\frac{n}{2}}.
\end{align*}
\item\label{t:full_rate_sublinear}
If $\kappa\in (\frac{1}{2},1)$, then there exists $\overline{\gamma}\in \mathbb{R}_{++}$ such that, for all $n\in \mathbb{N}$,
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}, \\
&\|\mathbf{Ax}_n+By_n-b\| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}, \\
&\lvert \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) -\mathcal{L}_\rho(\mathbf{x}^{*},y^{*},z^{*})\rvert \leq \overline{\gamma} n^{-\frac{2-2\kappa}{2\kappa-1}}, \\
\text{and~} &|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}.
\end{align*}
\end{enumerate}
\end{enumerate}
\end{theorem}

